def records(doc, label='segments'):
    if not isinstance(doc,(dict,list)):
        raise ValueError(f'{label} document must be an object or array')
    values = doc if isinstance(doc, list) else doc.get(label)
    if not isinstance(values, list):
        raise ValueError(f'{label} must be an array')
    return values

def parse_document(text):
    matches = list(HEADER.finditer(text))
    if not matches:
        raise ValueError('no AVS segment headers recognized')
    prefix, blocks = text[:matches[0].start()], []
    for n, match in enumerate(matches):
        end = matches[n+1].start() if n+1 < len(matches) else len(text)
        chunk = text[match.start():end]
        start = re.search(r'(?m)^(?:subject_definitions|integrated_multimodal_description):', chunk)
        if start is None:
            start = re.search(r'(?m)^(?:For the target video|How the reference pictures align)', chunk)
        if not start:
            raise ValueError(f'segment {n+1}: no H3 prompt start found')
        envelope, rest = chunk[:start.start()], chunk[start.start():]
        tail_match = re.search(r'(?:\r?\n[ \t]*)+(?:(?:---)[ \t]*\r?\n[ \t]*)?\Z', rest)
        prompt, tail = (rest[:tail_match.start()], rest[tail_match.start():]) if tail_match else (rest, '')
        metadata = {}
        for key, value in re.findall(r'(?m)^【([^】]+)】([^\r\n]*)', envelope):
            if key.startswith(('视频片段', '视频段', '第')):
                continue
            if key in metadata:
                raise ValueError(f'duplicate metadata {key}')
            metadata[key] = value.strip()
        missing = set(META_FIELDS) - metadata.keys()
        if missing:
            raise ValueError(f'segment {n+1}: missing AVS fields {sorted(missing)}')
        blocks.append(Segment(int(match[1] or match[2] or match[3]), float(match[4]), match[5].strip(), envelope, prompt, tail, metadata, binding_map(metadata['Picture绑定'], 'P'), binding_map(metadata['Speaker绑定'], 'S')))
    ids = [b.index for b in blocks]
    if ids != list(range(1, len(blocks)+1)):
        raise ValueError('AVS segment IDs must be consecutive in source order, starting at 1')
    return prefix, blocks

def validate_prompt(block, errors, warnings):
    p, idx = block.prompt.replace('\r\n', '\n'), block.index
    def fail(code):
        errors.append(f'SEGMENT_{idx}:{code}')
    mode = block.metadata['H3模式'].upper()
    fields = REF_FIELDS if mode == 'REF2VA' else BASE_FIELDS
    if mode not in {'REF2VA', 'T2VA', 'I2VA', 'FL2VA', 'L2VA'}:
        fail(f'UNKNOWN_H3_MODE:{mode}')
    heads = list(re.finditer(r'(?m)^([a-z][a-z_]*):[ \t]*', p))
    if [m[1] for m in heads] != fields:
        fail('TOP_LEVEL_SECTIONS_MISSING_DUPLICATED_OR_EXTRA')
        return
    sections = {m[1]: p[m.end():heads[i+1].start() if i+1 < len(heads) else len(p)].strip() for i, m in enumerate(heads)}
    if any(not value for value in sections.values()):
        fail('EMPTY_SECTION')
    if mode == 'REF2VA' and p[:heads[0].start()].strip():
        fail('TEXT_BEFORE_FIRST_SECTION')
    if re.search(r'^【|^```|^#{1,6}\s', p, re.M):
        fail('AVS_OR_MARKDOWN_IN_RUNTIME')
    for key in ENGINEERING:
        if re.search(rf'(?mi)^\s*(?:-\s*)?{key}\s*:', p):
            fail(f'ENGINEERING_FIELD_IN_RUNTIME:{key}')
    picture_refs = {f'P{x}' for x in re.findall(r'<Picture\s+(\d+)>', p)}
    if picture_refs != set(block.bindings):
        fail(f'PICTURE_BINDING_MISMATCH:unbound={sorted(picture_refs-set(block.bindings))},unused={sorted(set(block.bindings)-picture_refs)}')
    if len(block.bindings) > 9:
        fail('PICTURE_BUDGET_EXCEEDED')
    if mode == 'REF2VA':
        defs = definitions(p)
        if not defs:
            fail('REFERENCE_DEFINITIONS_EMPTY')
        source_videos = {tag for value in defs.values() for tag in value['sources'] if tag.startswith('Video ')}
        unknown = {t for t in tags(p) if not t.startswith('Picture ') and t not in defs and t not in source_videos}
        if unknown:
            fail(f'UNDEFINED_LABELS:{sorted(unknown)}')
        summary = sections['summary']
        task = re.match(r'^\[([^\]]+)\]', summary)
        allowed = {'reference generation', 'keyframe completion', 'video editing', 'video continuation', 'audio reuse', 'audio reference'}
        if not task or any(t.strip() not in allowed for t in task[1].split('+')):
            fail('SUMMARY_TASK_PREFIX_INVALID')
        if defs and not tags(summary).intersection(defs):
            fail('SUMMARY_MISSING_REFERENCE_LABELS')
        retention = sections['retention_analysis']
        for key in defs:
            lines = re.findall(rf'(?m)^<{re.escape(key)}>([^\n]*)', retention)
            markers = ['fully_copy', 'partially_copy', 'reference', 'weak_reference'] if key.startswith('Audio ') else ['fully_preserved', 'partially_preserved', 'attribute_transfer', 'weak_reference']
            marker_pattern = rf'^\s*(?:\([^\n]*\))?\s*:\s*(?:{"|".join(markers)})\s*[-–—]'
            if len(lines) != 1 or not re.search(marker_pattern,lines[0]):
                fail(f'RETENTION_ENTRY_MISSING_OR_INVALID:{key}')
        retention_keys = {f'{a} {b}' for a,b in re.findall(r'(?m)^<(Subject|Picture|Video|Audio)\s+(\d+)>', retention)}
        if retention_keys - defs.keys():
            fail('RETENTION_USES_UNDEFINED_OR_SOURCE_ONLY_LABEL')
        detail = sections['detailed_description']
        for key in defs:
            if key.startswith('Subject ') and f'<{key}>' not in detail:
                fail(f'SUBJECT_NOT_USED_IN_SHOTS:{key}')
        style = detail.split('[Shot 1]', 1)[0].strip()
        if not style:
            fail('REF_STYLE_OPENING_MISSING')
        words = len(re.findall(r'\b[A-Za-z]+(?:[-\x27][A-Za-z]+)*\b', detail))
        if not 350 <= words <= 500:
            warnings.append(f'SEGMENT_{idx}:DETAIL_WORD_COUNT_{words}:official_typical_range_350_500_not_a_parser_limit')
    else:
        detail = sections['integrated_multimodal_description']
        if mode != 'T2VA' and not p[:heads[0].start()].strip():
            fail('KEYFRAME_ALIGNMENT_INSTRUCTION_MISSING')
    shots = list(re.finditer(r'\[Shot\s+(\d+)\]', detail))
    if not shots or [int(m[1]) for m in shots] != list(range(1,len(shots)+1)):
        fail('SHOT_NUMBERS_INVALID')
    previous = 0.0
    for n, shot in enumerate(shots):
        following = detail[shot.end():]
        time = re.match(r'\s+At\s+(\d{2}):(\d{2})\.(\d{3}),', following)
        if n == 0:
            if time:
                fail('SHOT1_MUST_NOT_HAVE_TIMESTAMP')
            continue
        if not time:
            fail(f'SHOT_{n+1}_TIMESTAMP_MISSING')
            continue
        current = int(time[1])*60+int(time[2])+int(time[3])/1000
        if not previous < current < block.duration:
            fail(f'SHOT_{n+1}_TIMESTAMP_OUT_OF_ORDER_OR_DURATION')
        previous = current
    if len(shots) >= 3 and block.duration <= 5:
        warnings.append(f'SEGMENT_{idx}:SHORT_MULTI_SHOT_REQUIRES_FEASIBILITY_REVIEW')
    voice_ids = set(re.findall(r'\((S\d+)\)', detail))
    if not voice_ids.issubset(block.speakers):
        fail(f'UNBOUND_SPEAKERS:{sorted(voice_ids-set(block.speakers))}')
    if '<d>' in p and not re.search(r'<d>\[[^\]]+\]', p):
        fail('DIALOGUE_LANGUAGE_TAG_MISSING')

def validate_runtime_limits(project, blocks, errors, warnings):
    info = project.get('project', {}) if isinstance(project, dict) else {}
    if 'runtime_budget' not in info:
        return  # Preserve conversion-only legacy projects with frozen durations.
    budget = info['runtime_budget']
    def numeric(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)
    if not isinstance(budget, dict):
        errors.append('INVALID_RUNTIME_BUDGET')
        return
    target, maximum = budget.get('target_runtime_s'), budget.get('max_runtime_s')
    step = budget.get('segment_duration_s')
    if (not numeric(target) or not numeric(maximum) or not numeric(step)
            or step != 5 or target < step or target > maximum
            or target % step or maximum % step
            or budget.get('target_segment_count') != target / step
            or budget.get('max_segment_count') != maximum / step):
        errors.append('INVALID_RUNTIME_BUDGET')
        return
    if budget.get('profile') == 'BATCH_COMPACT':
        if (target, maximum) != (180, 240):
            errors.append('DEFAULT_RUNTIME_BUDGET_CHANGED_WITHOUT_OVERRIDE')
    elif budget.get('profile') != 'USER_DEFINED' or not str(budget.get('override_reason') or '').strip():
        errors.append('RUNTIME_BUDGET_OVERRIDE_REASON_MISSING')
    total = sum(b.duration for b in blocks)
    if len(blocks) > budget['max_segment_count']:
        errors.append('SEGMENT_BUDGET_EXCEEDED')
    if total > maximum:
        errors.append('RUNTIME_BUDGET_EXCEEDED')
    elif total > target:
        warnings.append('RUNTIME_ABOVE_TARGET_REVIEW_COMPRESSION')
    if any(b.duration != step for b in blocks):
        errors.append('RUNTIME_BUDGET_SEGMENT_DURATION_MISMATCH')
    declared = info.get('final_runtime_s')
    if not numeric(declared) or abs(declared - total) > 1e-6:
        errors.append('PROJECT_DECLARED_RUNTIME_MISMATCH')

def validate_document(text, project, assets, draft=None, segments=None, asset_root=None):
    errors, warnings, checked_paths = [], [], []
    prefix, blocks = parse_document(text)
    validate_runtime_limits(project, blocks, errors, warnings)
    expected = records(project)
    ids = [segment_id(x.get('segment_id')) for x in expected]
    if ids != [b.index for b in blocks]:
        errors.append('PROJECT_SEGMENT_ORDER_OR_COUNT_MISMATCH')
    declared_count = project.get('project', {}).get('final_segment_count') if isinstance(project, dict) else None
    if declared_count is not None and declared_count != len(blocks):
        errors.append('PROJECT_DECLARED_SEGMENT_COUNT_MISMATCH')
    plan = {segment_id(x.get('segment_id')): x for x in expected}
    asset_items = records(assets, 'assets')
    names = {}
    for a in asset_items:
        name = a.get('output_filename')
        if not isinstance(name, str) or not name:
            errors.append('ASSET_OUTPUT_FILENAME_MISSING')
            continue
        names.setdefault(name, []).append(a)
    for block in blocks:
        idx = block.index
        validate_prompt(block, errors, warnings)
        if not 0.2 <= block.duration <= 15.1:
            errors.append(f'SEGMENT_{idx}:DURATION_OUTSIDE_AVS_RANGE')
        if block.metadata['连续性'] not in {'独立生成', '续写上一段'}:
            errors.append(f'SEGMENT_{idx}:CONTINUITY_INVALID')
        if idx == 1 and block.metadata['连续性'] != '独立生成':
            errors.append('FIRST_SEGMENT_CANNOT_CONTINUE_PREVIOUS')
        if block.metadata['继承尾音'] not in {'是', '否'}:
            errors.append(f'SEGMENT_{idx}:AUDIO_INHERITANCE_INVALID')
        source = plan.get(idx, {})
        registry = source.get('subject_registry',{})
        if registry and block.metadata['H3模式'].upper() == 'REF2VA':
            defs = definitions(block.prompt)
            for key,value in registry.items():
                if key not in defs or set(value.get('sources',[])) != defs[key]['sources']:
                    errors.append(f'SEGMENT_{idx}:PROJECT_REFERENCE_REGISTRY_MISMATCH:{key}')
        duration = source.get('duration_s')
        if duration is None or isinstance(duration, bool) or abs(float(duration)-block.duration)>1e-6:
            errors.append(f'SEGMENT_{idx}:PROJECT_DURATION_MISMATCH')
        comparisons = [('title',block.title),('name',block.title),('continuity',block.metadata['连续性']),('inherit_previous_audio',block.metadata['继承尾音']=='是'),('picture_bindings',block.bindings),('speaker_bindings',block.speakers)]
        for key,value in comparisons:
            if key in source and source[key] != value:
                errors.append(f'SEGMENT_{idx}:PROJECT_{key.upper()}_MISMATCH')
        for field,prefix_field in [('集数','episode'),('场景','scene')]:
            parts = re.split('[｜|]',block.metadata[field],maxsplit=1)
            for key,value in [(prefix_field+'_id',parts[0]),(prefix_field+'_name',parts[1] if len(parts)>1 else '')]:
                if key in source and source[key] != value:
                    errors.append(f'SEGMENT_{idx}:PROJECT_{key.upper()}_MISMATCH')
        if 'current_segment_dialogue' not in source:
            errors.append(f'SEGMENT_{idx}:PROJECT_DIALOGUE_CONTRACT_MISSING')
        else:
            dialogue = [x.get('text') if isinstance(x,dict) else x for x in source['current_segment_dialogue']]
            spoken = re.findall(r'<d>\[[^\]]+\]\s*(.*?)</d>',block.prompt,re.S)
            spoken = [x.strip() for x in spoken]
            if dialogue != spoken:
                errors.append(f'SEGMENT_{idx}:DIALOGUE_TEXT_ORDER_OR_COUNT_MISMATCH')
        if source.get('screen_direction_unresolved'):
            errors.append(f'SEGMENT_{idx}:SCREEN_DIRECTION_UNRESOLVED')
        if source.get('jump_risk_from_previous') == 'HIGH' and not source.get('bridge_reason') and not source.get('off_screen_state_changes'):
            errors.append(f'SEGMENT_{idx}:UNRESOLVED_HIGH_CONTINUITY_JUMP')
        for label in block.bindings.values():
            entries = names.get(label,[])
            if len(entries) != 1:
                errors.append(f'SEGMENT_{idx}:ASSET_UNKNOWN_OR_AMBIGUOUS:{label}')
                continue
            a = entries[0]
            if a.get('direct_bindable') is False:
                errors.append(f'SEGMENT_{idx}:ASSET_NOT_DIRECT_BINDABLE:{label}')
            if asset_root:
                raw = a.get('path') or str(Path(a.get('relative_dir','')) / label)
                path = Path(raw)
                if not path.is_absolute():
                    path = Path(asset_root)/path
                checked_paths.append(str(path.resolve()))
                if not path.is_file():
                    errors.append(f'SEGMENT_{idx}:ASSET_FILE_MISSING:{path}')
    if isinstance(project,dict) and 'source_beats' in project:
        covered = {bid for s in expected for bid in s.get('source_beat_ids',[])}
        known = {b.get('beat_id') for b in project['source_beats']}
        if covered-known:
            errors.append('UNKNOWN_SOURCE_BEAT_IDS')
        for beat in project['source_beats']:
            if beat.get('preservation') in {'EXACT','VISUAL_EQUIVALENT'} and beat.get('beat_id') not in covered:
                errors.append(f'PROTECTED_SOURCE_BEAT_UNCOVERED:{beat.get("beat_id")}')
    if draft is not None:
        old_prefix, old = parse_document(draft)
        if prefix != old_prefix or len(old) != len(blocks):
            errors.append('DRAFT_OUTER_STRUCTURE_CHANGED')
        else:
            for a,b in zip(old,blocks):
                if a.envelope != b.envelope or a.tail != b.tail:
                    errors.append(f'SEGMENT_{b.index}:DRAFT_ENVELOPE_CHANGED')
                if b.metadata['H3模式'].upper() == 'REF2VA':
                    left,right = definitions(a.prompt),definitions(b.prompt)
                    if left.keys() != right.keys() or any(left[k]['sources'] != right[k]['sources'] for k in left.keys()&right.keys()):
                        errors.append(f'SEGMENT_{b.index}:REFERENCE_LABELS_OR_SOURCES_CHANGED')
    if segments is not None:
        rows = records(segments)
        if [segment_id(s.get('segment_id')) for s in rows] != [b.index for b in blocks]:
            errors.append('SEGMENTS_JSON_ORDER_OR_COUNT_MISMATCH')
        else:
            for s,b in zip(rows,blocks):
                if s.get('full_prompt') != b.prompt:
                    errors.append(f'SEGMENT_{b.index}:SEGMENTS_JSON_PROMPT_MISMATCH')
                if 'duration_s' in s and float(s['duration_s']) != b.duration:
                    errors.append(f'SEGMENT_{b.index}:SEGMENTS_JSON_DURATION_MISMATCH')
    return {'structure_status':'FAIL' if errors else 'PASS','errors':errors,'warnings':warnings,'segment_count':len(blocks),'asset_files_status':'CHECK_FAILED' if any('ASSET_FILE_MISSING' in e for e in errors) else ('VERIFIED' if asset_root else 'UNVERIFIED'),'checked_asset_paths':sorted(set(checked_paths)),'semantic_status':'NOT_REVIEWED_BY_THIS_CHECK','video_quality_status':'NOT_TESTED'}

def main(path):
    text=Path(path).read_text(encoding="utf-8-sig").replace("\r\n","\n")
    lines=text.splitlines()
    starts=[]
    for i,line in enumerate(lines):
        if FORMAL.match(line) or LOCK.match(line): starts.append(i)
    errors=[]; warnings=[]; blocks=[]
    if not starts: errors.append("NO_WORKBENCH_HEADERS")
    for n,start in enumerate(starts):
        end=starts[n+1] if n+1<len(starts) else len(lines)
        head=lines[start]; fm=FORMAL.match(head); lm=LOCK.match(head)
        role="content" if fm else "hidden_anchor"
        ident=int(fm[1] or fm[2]) if fm else lm[1].strip()
        dur=float(fm[3] if fm else lm[2])
        chunk=lines[start:end]
        meta={}
        prompt_start=None
        for j,line in enumerate(chunk[1:],1):
            if START.match(line): prompt_start=j; break
            m=META.match(line)
            if m: meta[m[1]]=m[2].strip()
        if prompt_start is None:
            errors.append(f"{ident}:PROMPT_START_MISSING"); prompt=""
        else: prompt="\n".join(chunk[prompt_start:]).strip()
        blocks.append({"role":role,"id":ident,"duration":dur,"meta":meta,"prompt":prompt})
    formal=[b for b in blocks if b["role"]=="content"]
    ids=[b["id"] for b in formal]
    if ids!=list(range(1,len(ids)+1)): errors.append("FORMAL_IDS_NOT_CONSECUTIVE")
    lock_ids=[b["id"] for b in blocks if b["role"]=="hidden_anchor"]
    if len(lock_ids)!=len(set(lock_ids)): errors.append("DUPLICATE_LOCK_ID")
    for i,b in enumerate(blocks):
        m=b["meta"]
        for key in ["集数","场景","H3模式","连续性","继承尾音","生成模式","Picture绑定","Speaker绑定"]:
            if key not in m: errors.append(f"{b['id']}:META_MISSING:{key}")
        if m.get("H3模式","").upper()=="REF2VA":
            pos=[b["prompt"].find(x) for x in SECTIONS_REF]
            if any(x<0 for x in pos) or pos!=sorted(pos): errors.append(f"{b['id']}:REF2VA_SECTIONS_INVALID")
        raw_bind=m.get("Picture绑定","")
        bound=set() if raw_bind in {"","无","N/A","none"} else {x.upper() for x in re.findall(r"(?:^|[；;,，])\s*(P[1-9])\s*[=:：]",raw_bind,re.I)}
        refs={f"P{int(n)}" for n in re.findall(r"<Picture\s+(\d+)>",b["prompt"],re.I)}
        if bound != refs: errors.append(f"{b['id']}:PICTURE_BINDING_MISMATCH:bound={sorted(bound)},refs={sorted(refs)}")
        if b["role"]=="hidden_anchor":
            if not .2<=b["duration"]<=15.1: errors.append(f"{b['id']}:DURATION_OUTSIDE_AVS")
            if not .8<=b["duration"]<=1.5: warnings.append(f"{b['id']}:LOCK_DURATION_RECOMMENDED_0.8_TO_1.5S")
            if m.get("段类型")!="隐藏空间预热": errors.append(f"{b['id']}:ROLE_METADATA_INVALID")
            if m.get("成片")!="否": errors.append(f"{b['id']}:HIDDEN_MUST_NOT_BE_IN_FINAL")
            if m.get("空间锁ID")!=b["id"]: errors.append(f"{b['id']}:LOCK_ID_MISMATCH")
            if m.get("连续性")!="独立生成": errors.append(f"{b['id']}:LOCK_MUST_BE_INDEPENDENT")
            if m.get("继承尾音")!="否": errors.append(f"{b['id']}:LOCK_MUST_NOT_INHERIT_AUDIO")
            if "<d>" in b["prompt"]: errors.append(f"{b['id']}:LOCK_HAS_DIALOGUE")
            if i+1>=len(blocks) or blocks[i+1]["role"]!="content": errors.append(f"{b['id']}:LOCK_MUST_IMMEDIATELY_PRECEDE_FORMAL")
            else:
                nxt=blocks[i+1]
                if nxt["meta"].get("空间锁来源")!=b["id"]: errors.append(f"{b['id']}:NEXT_FORMAL_LOCK_SOURCE_MISMATCH")
                if nxt["meta"].get("连续性")!="续写上一段": errors.append(f"{b['id']}:NEXT_FORMAL_MUST_CONTINUE")
                if nxt["meta"].get("继承尾音")!="否": errors.append(f"{b['id']}:NEXT_FORMAL_MUST_NOT_INHERIT_LOCK_AUDIO")
                if nxt["meta"].get("场景")!=m.get("场景"): errors.append(f"{b['id']}:SCENE_MISMATCH")
        else:
            if m.get("段类型") not in {None,"正式视频段"}: errors.append(f"SEG{b['id']}:ROLE_METADATA_INVALID")
            if m.get("成片") not in {None,"是"}: errors.append(f"SEG{b['id']}:FORMAL_MUST_BE_IN_FINAL")
    payload={"ok":not errors,"formal_segments":len(formal),"hidden_locks":len(lock_ids),"errors":errors,"warnings":warnings}
    print(json.dumps(payload,ensure_ascii=False,indent=2))
    return 1 if errors else 0

