def records(doc, label='segments'):
    if not isinstance(doc,(dict,list)):
        raise ValueError(f'{label} document must be an object or array')
    values = doc if isinstance(doc, list) else doc.get(label)
    if not isinstance(values, list):
        raise ValueError(f'{label} must be an array')
    return values

def parse_document(text):
    matches = list(HEADER.finditer(text))
    if not matches:
        raise ValueError('no AVS segment headers recognized')
    prefix, blocks = text[:matches[0].start()], []
    for n, match in enumerate(matches):
        end = matches[n+1].start() if n+1 < len(matches) else len(text)
        chunk = text[match.start():end]
        start = re.search(r'(?m)^(?:subject_definitions|integrated_multimodal_description):', chunk)
        if start is None:
            start = re.search(r'(?m)^(?:For the target video|How the reference pictures align)', chunk)
        if not start:
            raise ValueError(f'segment {n+1}: no H3 prompt start found')
        envelope, rest = chunk[:start.start()], chunk[start.start():]
        tail_match = re.search(r'(?:\r?\n[ \t]*)+(?:(?:---)[ \t]*\r?\n[ \t]*)?\Z', rest)
        prompt, tail = (rest[:tail_match.start()], rest[tail_match.start():]) if tail_match else (rest, '')
        metadata = {}
        for key, value in re.findall(r'(?m)^【([^】]+)】([^\r\n]*)', envelope):
            if key.startswith(('视频片段', '视频段', '第')):
                continue
            if key in metadata:
                raise ValueError(f'duplicate metadata {key}')
            metadata[key] = value.strip()
        missing = set(META_FIELDS) - metadata.keys()
        if missing:
            raise ValueError(f'segment {n+1}: missing AVS fields {sorted(missing)}')
        blocks.append(Segment(int(match[1] or match[2] or match[3]), float(match[4]), match[5].strip(), envelope, prompt, tail, metadata, binding_map(metadata['Picture绑定'], 'P'), binding_map(metadata['Speaker绑定'], 'S')))
    ids = [b.index for b in blocks]
    if ids != list(range(1, len(blocks)+1)):
        raise ValueError('AVS segment IDs must be consecutive in source order, starting at 1')
    return prefix, blocks

def validate_prompt(block, errors, warnings):
    p, idx = block.prompt.replace('\r\n', '\n'), block.index
    def fail(code):
        errors.append(f'SEGMENT_{idx}:{code}')
    mode = block.metadata['H3模式'].upper()
    fields = REF_FIELDS if mode == 'REF2VA' else BASE_FIELDS
    if mode not in {'REF2VA', 'T2VA', 'I2VA', 'FL2VA', 'L2VA'}:
        fail(f'UNKNOWN_H3_MODE:{mode}')
    heads = list(re.finditer(r'(?m)^([a-z][a-z_]*):[ \t]*', p))
    if [m[1] for m in heads] != fields:
        fail('TOP_LEVEL_SECTIONS_MISSING_DUPLICATED_OR_EXTRA')
        return
    sections = {m[1]: p[m.end():heads[i+1].start() if i+1 < len(heads) else len(p)].strip() for i, m in enumerate(heads)}
    if any(not value for value in sections.values()):
        fail('EMPTY_SECTION')
    if mode == 'REF2VA' and p[:heads[0].start()].strip():
        fail('TEXT_BEFORE_FIRST_SECTION')
    if re.search(r'^【|^```|^#{1,6}\s', p, re.M):
        fail('AVS_OR_MARKDOWN_IN_RUNTIME')
    for key in ENGINEERING:
        if re.search(rf'(?mi)^\s*(?:-\s*)?{key}\s*:', p):
            fail(f'ENGINEERING_FIELD_IN_RUNTIME:{key}')
    picture_refs = {f'P{x}' for x in re.findall(r'<Picture\s+(\d+)>', p)}
    if picture_refs != set(block.bindings):
        fail(f'PICTURE_BINDING_MISMATCH:unbound={sorted(picture_refs-set(block.bindings))},unused={sorted(set(block.bindings)-picture_refs)}')
    if len(block.bindings) > 9:
        fail('PICTURE_BUDGET_EXCEEDED')
    if mode == 'REF2VA':
        defs = definitions(p)
        if not defs:
            fail('REFERENCE_DEFINITIONS_EMPTY')
        source_videos = {tag for value in defs.values() for tag in value['sources'] if tag.startswith('Video ')}
        unknown = {t for t in tags(p) if not t.startswith('Picture ') and t not in defs and t not in source_videos}
        if unknown:
            fail(f'UNDEFINED_LABELS:{sorted(unknown)}')
        summary = sections['summary']
        task = re.match(r'^\[([^\]]+)\]', summary)
        allowed = {'reference generation', 'keyframe completion', 'video editing', 'video continuation', 'audio reuse', 'audio reference'}
        if not task or any(t.strip() not in allowed for t in task[1].split('+')):
            fail('SUMMARY_TASK_PREFIX_INVALID')
        if defs and not tags(summary).intersection(defs):
            fail('SUMMARY_MISSING_REFERENCE_LABELS')
        retention = sections['retention_analysis']
        for key in defs:
            lines = re.findall(rf'(?m)^<{re.escape(key)}>([^\n]*)', retention)
            markers = ['fully_copy', 'partially_copy', 'reference', 'weak_reference'] if key.startswith('Audio ') else ['fully_preserved', 'partially_preserved', 'attribute_transfer', 'weak_reference']
            marker_pattern = rf'^\s*(?:\([^\n]*\))?\s*:\s*(?:{"|".join(markers)})\s*[-–—]'
            if len(lines) != 1 or not re.search(marker_pattern,lines[0]):
                fail(f'RETENTION_ENTRY_MISSING_OR_INVALID:{key}')
        retention_keys = {f'{a} {b}' for a,b in re.findall(r'(?m)^<(Subject|Picture|Video|Audio)\s+(\d+)>', retention)}
        if retention_keys - defs.keys():
            fail('RETENTION_USES_UNDEFINED_OR_SOURCE_ONLY_LABEL')
        detail = sections['detailed_description']
        for key in defs:
            if key.startswith('Subject ') and f'<{key}>' not in detail:
                fail(f'SUBJECT_NOT_USED_IN_SHOTS:{key}')
        style = detail.split('[Shot 1]', 1)[0].strip()
        if not style:
            fail('REF_STYLE_OPENING_MISSING')
        words = len(re.findall(r'\b[A-Za-z]+(?:[-\x27][A-Za-z]+)*\b', detail))
        if not 350 <= words <= 500:
            warnings.append(f'SEGMENT_{idx}:DETAIL_WORD_COUNT_{words}:official_typical_range_350_500_not_a_parser_limit')
    else:
        detail = sections['integrated_multimodal_description']
        if mode != 'T2VA' and not p[:heads[0].start()].strip():
            fail('KEYFRAME_ALIGNMENT_INSTRUCTION_MISSING')
    shots = list(re.finditer(r'\[Shot\s+(\d+)\]', detail))
    if not shots or [int(m[1]) for m in shots] != list(range(1,len(shots)+1)):
        fail('SHOT_NUMBERS_INVALID')
    previous = 0.0
    for n, shot in enumerate(shots):
        following = detail[shot.end():]
        time = re.match(r'\s+At\s+(\d{2}):(\d{2})\.(\d{3}),', following)
        if n == 0:
            if time:
                fail('SHOT1_MUST_NOT_HAVE_TIMESTAMP')
            continue
        if not time:
            fail(f'SHOT_{n+1}_TIMESTAMP_MISSING')
            continue
        current = int(time[1])*60+int(time[2])+int(time[3])/1000
        if not previous < current < block.duration:
            fail(f'SHOT_{n+1}_TIMESTAMP_OUT_OF_ORDER_OR_DURATION')
        previous = current
    if len(shots) >= 3 and block.duration <= 5:
        warnings.append(f'SEGMENT_{idx}:SHORT_MULTI_SHOT_REQUIRES_FEASIBILITY_REVIEW')
    voice_ids = set(re.findall(r'\((S\d+)\)', detail))
    if not voice_ids.issubset(block.speakers):
        fail(f'UNBOUND_SPEAKERS:{sorted(voice_ids-set(block.speakers))}')
    if '<d>' in p and not re.search(r'<d>\[[^\]]+\]', p):
        fail('DIALOGUE_LANGUAGE_TAG_MISSING')

def validate_runtime_limits(project, blocks, errors, warnings):
    info = project.get('project', {}) if isinstance(project, dict) else {}
    if 'runtime_budget' not in info:
        return  # Preserve conversion-only legacy projects with frozen durations.
    budget = info['runtime_budget']
    def numeric(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)
    if not isinstance(budget, dict):
        errors.append('INVALID_RUNTIME_BUDGET')
        return
    target, maximum = budget.get('target_runtime_s'), budget.get('max_runtime_s')
    step = budget.get('segment_duration_s')
    if (not numeric(target) or not numeric(maximum) or not numeric(step)
            or step != 5 or target < step or target > maximum
            or target % step or maximum % step
            or budget.get('target_segment_count') != target / step
            or budget.get('max_segment_count') != maximum / step):
        errors.append('INVALID_RUNTIME_BUDGET')
        return
    if budget.get('profile') == 'BATCH_COMPACT':
        if (target, maximum) != (180, 240):
            errors.append('DEFAULT_RUNTIME_BUDGET_CHANGED_WITHOUT_OVERRIDE')
    elif budget.get('profile') != 'USER_DEFINED' or not str(budget.get('override_reason') or '').strip():
        errors.append('RUNTIME_BUDGET_OVERRIDE_REASON_MISSING')
    total = sum(b.duration for b in blocks)
    if len(blocks) > budget['max_segment_count']:
        errors.append('SEGMENT_BUDGET_EXCEEDED')
    if total > maximum:
        errors.append('RUNTIME_BUDGET_EXCEEDED')
    elif total > target:
        warnings.append('RUNTIME_ABOVE_TARGET_REVIEW_COMPRESSION')
    if any(b.duration != step for b in blocks):
        errors.append('RUNTIME_BUDGET_SEGMENT_DURATION_MISMATCH')
    declared = info.get('final_runtime_s')
    if not numeric(declared) or abs(declared - total) > 1e-6:
        errors.append('PROJECT_DECLARED_RUNTIME_MISMATCH')

def validate_document(text, project, assets, draft=None, segments=None, asset_root=None):
    errors, warnings, checked_paths = [], [], []
    prefix, blocks = parse_document(text)
    validate_runtime_limits(project, blocks, errors, warnings)
    style_errors = validate_style_contract(project, assets, blocks)
    errors.extend(style_errors)
    expected = records(project)
    if isinstance(project, dict):
        errors.extend(validate_schedule(project))
    ids = [segment_id(x.get('segment_id')) for x in expected]
    if ids != [b.index for b in blocks]:
        errors.append('PROJECT_SEGMENT_ORDER_OR_COUNT_MISMATCH')
    declared_count = project.get('project', {}).get('final_segment_count') if isinstance(project, dict) else None
    if declared_count is not None and declared_count != len(blocks):
        errors.append('PROJECT_DECLARED_SEGMENT_COUNT_MISMATCH')
    plan = {segment_id(x.get('segment_id')): x for x in expected}
    asset_items = records(assets, 'assets')
    names = {}
    for a in asset_items:
        name = a.get('output_filename')
        if not isinstance(name, str) or not name:
            errors.append('ASSET_OUTPUT_FILENAME_MISSING')
            continue
        names.setdefault(name, []).append(a)
    for block in blocks:
        idx = block.index
        validate_prompt(block, errors, warnings)
        if not 0.2 <= block.duration <= 15.1:
            errors.append(f'SEGMENT_{idx}:DURATION_OUTSIDE_AVS_RANGE')
        if block.metadata['连续性'] not in {'独立生成', '续写上一段'}:
            errors.append(f'SEGMENT_{idx}:CONTINUITY_INVALID')
        if idx == 1 and block.metadata['连续性'] != '独立生成':
            errors.append('FIRST_SEGMENT_CANNOT_CONTINUE_PREVIOUS')
        if block.metadata['继承尾音'] not in {'是', '否'}:
            errors.append(f'SEGMENT_{idx}:AUDIO_INHERITANCE_INVALID')
        source = plan.get(idx, {})
        errors.extend(validate_prompt_schedule(block.prompt, source))
        registry = source.get('subject_registry',{})
        if registry and block.metadata['H3模式'].upper() == 'REF2VA':
            defs = definitions(block.prompt)
            for key,value in registry.items():
                if key not in defs or set(value.get('sources',[])) != defs[key]['sources']:
                    errors.append(f'SEGMENT_{idx}:PROJECT_REFERENCE_REGISTRY_MISMATCH:{key}')
        duration = source.get('duration_s')
        if duration is None or isinstance(duration, bool) or abs(float(duration)-block.duration)>1e-6:
            errors.append(f'SEGMENT_{idx}:PROJECT_DURATION_MISMATCH')
        comparisons = [('title',block.title),('name',block.title),('continuity',block.metadata['连续性']),('inherit_previous_audio',block.metadata['继承尾音']=='是'),('picture_bindings',block.bindings),('speaker_bindings',block.speakers)]
        for key,value in comparisons:
            if key in source and source[key] != value:
                errors.append(f'SEGMENT_{idx}:PROJECT_{key.upper()}_MISMATCH')
        for field,prefix_field in [('集数','episode'),('场景','scene')]:
            parts = re.split('[｜|]',block.metadata[field],maxsplit=1)
            for key,value in [(prefix_field+'_id',parts[0]),(prefix_field+'_name',parts[1] if len(parts)>1 else '')]:
                if key in source and source[key] != value:
                    errors.append(f'SEGMENT_{idx}:PROJECT_{key.upper()}_MISMATCH')
        if 'current_segment_dialogue' not in source:
            errors.append(f'SEGMENT_{idx}:PROJECT_DIALOGUE_CONTRACT_MISSING')
        else:
            dialogue = [x.get('text') if isinstance(x,dict) else x for x in source['current_segment_dialogue']]
            spoken = re.findall(r'<d>\[[^\]]+\]\s*(.*?)</d>',block.prompt,re.S)
            spoken = [x.strip() for x in spoken]
            if dialogue != spoken:
                errors.append(f'SEGMENT_{idx}:DIALOGUE_TEXT_ORDER_OR_COUNT_MISMATCH')
        if source.get('screen_direction_unresolved'):
            errors.append(f'SEGMENT_{idx}:SCREEN_DIRECTION_UNRESOLVED')
        if source.get('jump_risk_from_previous') == 'HIGH' and not source.get('bridge_reason') and not source.get('off_screen_state_changes'):
            errors.append(f'SEGMENT_{idx}:UNRESOLVED_HIGH_CONTINUITY_JUMP')
        for label in block.bindings.values():
            entries = names.get(label,[])
            if len(entries) != 1:
                errors.append(f'SEGMENT_{idx}:ASSET_UNKNOWN_OR_AMBIGUOUS:{label}')
                continue
            a = entries[0]
            if a.get('direct_bindable') is False:
                errors.append(f'SEGMENT_{idx}:ASSET_NOT_DIRECT_BINDABLE:{label}')
            if asset_root:
                raw = a.get('path') or str(Path(a.get('relative_dir','')) / label)
                path = Path(raw)
                if not path.is_absolute():
                    path = Path(asset_root)/path
                checked_paths.append(str(path.resolve()))
                if not path.is_file():
                    errors.append(f'SEGMENT_{idx}:ASSET_FILE_MISSING:{path}')
    if isinstance(project,dict) and 'source_beats' in project:
        covered = {bid for s in expected for bid in s.get('source_beat_ids',[])}
        known = {b.get('beat_id') for b in project['source_beats']}
        if covered-known:
            errors.append('UNKNOWN_SOURCE_BEAT_IDS')
        for beat in project['source_beats']:
            if (beat.get('preservation') in {'EXACT','VISUAL_EQUIVALENT'} or beat.get('priority') == 'CORE') and beat.get('beat_id') not in covered:
                errors.append(f'PROTECTED_SOURCE_BEAT_UNCOVERED:{beat.get("beat_id")}')
    if draft is not None:
        old_prefix, old = parse_document(draft)
        if prefix != old_prefix or len(old) != len(blocks):
            errors.append('DRAFT_OUTER_STRUCTURE_CHANGED')
        else:
            for a,b in zip(old,blocks):
                if a.envelope != b.envelope or a.tail != b.tail:
                    errors.append(f'SEGMENT_{b.index}:DRAFT_ENVELOPE_CHANGED')
                if prompt_starts(a.prompt) != prompt_starts(b.prompt):
                    errors.append(f'SEGMENT_{b.index}:DRAFT_CUT_SCHEDULE_CHANGED')
                if b.metadata['H3模式'].upper() == 'REF2VA':
                    left,right = definitions(a.prompt),definitions(b.prompt)
                    if left.keys() != right.keys() or any(left[k]['sources'] != right[k]['sources'] for k in left.keys()&right.keys()):
                        errors.append(f'SEGMENT_{b.index}:REFERENCE_LABELS_OR_SOURCES_CHANGED')
    if segments is not None:
        rows = records(segments)
        if [segment_id(s.get('segment_id')) for s in rows] != [b.index for b in blocks]:
            errors.append('SEGMENTS_JSON_ORDER_OR_COUNT_MISMATCH')
        else:
            for s,b in zip(rows,blocks):
                if s.get('full_prompt') != b.prompt:
                    errors.append(f'SEGMENT_{b.index}:SEGMENTS_JSON_PROMPT_MISMATCH')
                if 'duration_s' in s and float(s['duration_s']) != b.duration:
                    errors.append(f'SEGMENT_{b.index}:SEGMENTS_JSON_DURATION_MISMATCH')
                if 'shot_plan' in plan.get(b.index, {}) and s.get('shot_plan') != plan[b.index]['shot_plan']:
                    errors.append(f'SEGMENT_{b.index}:SEGMENTS_JSON_SHOT_PLAN_MISMATCH')
    shot_counts = [len(prompt_starts(b.prompt)) for b in blocks]
    return {'style_status':'FAIL' if style_errors else 'PASS','structure_status':'FAIL' if errors else 'PASS','errors':errors,'warnings':warnings,'segment_count':len(blocks),'real_shot_count':sum(shot_counts),'multi_shot_segment_count':sum(n>1 for n in shot_counts),'single_shot_exceptions':[{'segment_id':s.get('segment_id'),'exception':s.get('single_shot_exception')} for s in expected if isinstance(s.get('shot_plan'),list) and len(s['shot_plan'])==1],'shot_schedule_status':('CHECK_FAILED' if any('SHOT' in e or 'CUT_' in e for e in errors) else 'VERIFIED') if isinstance(project,dict) and shot_contract_enabled(project) else 'LEGACY_NO_FROZEN_PLAN','asset_files_status':'CHECK_FAILED' if any('ASSET_FILE_MISSING' in e for e in errors) else ('VERIFIED' if asset_root else 'UNVERIFIED'),'checked_asset_paths':sorted(set(checked_paths)),'semantic_status':'NOT_REVIEWED_BY_THIS_CHECK','video_quality_status':'NOT_TESTED'}

def plan_budget(source_characters, target_seconds=DEFAULT_TARGET_S,
                max_seconds=DEFAULT_MAX_S, override_reason=""):
    if not isinstance(source_characters, int) or isinstance(source_characters, bool) or source_characters < 1:
        raise ValueError("source_characters must be a positive integer")
    for label, value in (("target_seconds", target_seconds), ("max_seconds", max_seconds)):
        if not number(value) or value < SEGMENT_S or value % SEGMENT_S:
            raise ValueError(f"{label} must be a positive multiple of {SEGMENT_S}")
    if target_seconds > max_seconds:
        raise ValueError("target_seconds cannot exceed max_seconds")
    custom = (target_seconds, max_seconds) != (DEFAULT_TARGET_S, DEFAULT_MAX_S)
    if custom and not override_reason.strip():
        raise ValueError("a user-defined budget requires override_reason")
    return {
        "profile": "USER_DEFINED" if custom else "BATCH_COMPACT",
        "source_character_count": source_characters,
        "segment_duration_s": SEGMENT_S,
        "target_runtime_s": target_seconds,
        "max_runtime_s": max_seconds,
        "target_segment_count": int(target_seconds / SEGMENT_S),
        "max_segment_count": int(max_seconds / SEGMENT_S),
        "override_reason": override_reason.strip() if custom else "",
    }

def validate_schedule(project):
    if not enabled(project):
        return []
    errors, global_ids = [], []
    for segment in project.get('segments', []):
        label = f'SEGMENT_{segment.get("segment_id")}'
        shots = segment.get('shot_plan')
        if not isinstance(shots, list) or not shots:
            errors.append(f'{label}:SHOT_PLAN_MISSING')
            continue
        previous = 0.0
        for n, shot in enumerate(shots, 1):
            if not isinstance(shot, dict):
                errors.append(f'{label}:SHOT_PLAN_ENTRY_INVALID')
                continue
            sid = shot.get('shot_id')
            if not isinstance(sid, str) or not re.fullmatch(r'SH\d{3,}', sid):
                errors.append(f'{label}:GLOBAL_SHOT_ID_INVALID')
            else:
                global_ids.append(sid)
            if shot.get('shot_number') != n:
                errors.append(f'{label}:SHOT_PLAN_ORDER_INVALID')
            start, end, duration = (shot.get(k) for k in ('start_s', 'end_s', 'duration_s'))
            if not all(finite(x) for x in (start, end, duration)):
                errors.append(f'{label}:SHOT_PLAN_TIME_INVALID')
                continue
            if abs(start - previous) > 1e-6 or end <= start:
                errors.append(f'{label}:SHOT_PLAN_GAP_OR_OVERLAP')
            if abs(duration - (end-start)) > 1e-6:
                errors.append(f'{label}:SHOT_DURATION_MISMATCH')
            if any(abs(value*1000-round(value*1000))>1e-6 for value in (start,end)):
                errors.append(f'{label}:SHOT_TIME_NOT_MILLISECOND_ALIGNED')
            if duration < 0.2:
                errors.append(f'{label}:SHOT_TOO_SHORT_FOR_THIS_ADAPTER')
            for field in ('shot_scale', 'camera_angle', 'camera_movement', 'composition', 'cut_reason', 'incoming_state', 'end_state'):
                if not isinstance(shot.get(field), str) or not shot[field].strip():
                    errors.append(f'{label}:SHOT_PLAN_FIELD_MISSING:{n}:{field}')
            if n > 1:
                last = shots[n-2]
                if isinstance(last, dict):
                    if shot.get('incoming_state') != last.get('end_state'):
                        errors.append(f'{label}:CUT_STATE_HANDOFF_MISMATCH:{n}')
                    if all(shot.get(k) == last.get(k) for k in ('shot_scale', 'camera_angle', 'composition')):
                        errors.append(f'{label}:CUT_VIEW_UNCHANGED:{n}')
            previous = end
        duration = segment.get('duration_s')
        if not finite(duration) or abs(previous-duration) > 1e-6:
            errors.append(f'{label}:SHOT_PLAN_END_MISMATCH')
        if isinstance(shots[0], dict) and shots[0].get('incoming_state') != segment.get('incoming_state'):
            errors.append(f'{label}:FIRST_SHOT_STATE_MISMATCH')
        if isinstance(shots[-1], dict) and shots[-1].get('end_state') != segment.get('end_state'):
            errors.append(f'{label}:LAST_SHOT_STATE_MISMATCH')
        expected_cuts = [s.get('start_s') for s in shots[1:] if isinstance(s, dict)]
        cuts = segment.get('planned_cut_times_s')
        if not isinstance(cuts, list) or len(cuts) != len(expected_cuts) or any(not finite(a) or not finite(b) or abs(a-b)>1e-6 for a,b in zip(cuts, expected_cuts)):
            errors.append(f'{label}:PLANNED_CUT_LIST_MISMATCH')
        if len(shots) == 1:
            exception = segment.get('single_shot_exception', {})
            categories = {'empty_transition', 'continuous_contact_action', 'unbroken_dialogue_performance', 'explicit_user_lock'}
            if project.get('project', {}).get('shot_design_policy') != 'story_driven_2d' and (not isinstance(exception, dict) or exception.get('category') not in categories or not str(exception.get('reason', '')).strip()):
                errors.append(f'{label}:UNJUSTIFIED_SINGLE_SHOT')
            if segment.get('multi_shot_required'):
                errors.append(f'{label}:MULTI_SHOT_REQUIRED')
            if segment.get('cut_policy') != 'single_continuous_shot':
                errors.append(f'{label}:CUT_POLICY_MISMATCH')
        elif segment.get('cut_policy') != 'multi_shot':
            errors.append(f'{label}:CUT_POLICY_MISMATCH')
    if len(set(global_ids)) != len(global_ids):
        errors.append('GLOBAL_SHOT_ID_DUPLICATE')
    return errors

def validate_style_contract(project, assets, blocks=None):
    errors = []
    info = project.get('project', {})
    mode = info.get('production_mode')
    if mode not in ('ANIMATED_COMIC', 'COMIC_STILLS'):
        errors.append('PRODUCTION_MODE_MISSING_OR_INVALID')
    if info.get('visual_medium') != '2D':
        errors.append('PROJECT_VISUAL_MEDIUM_NOT_2D')
    style_id, style = info.get('style_id'), info.get('visual_style')
    if not populated(style_id):
        errors.append('PROJECT_STYLE_ID_MISSING')
    if not populated(style) or not re.search(r'\b2[- ]?D\b|二维', str(style), re.I):
        errors.append('PROJECT_2D_STYLE_MISSING')
    if conflicts(style):
        errors.append('PROJECT_POSITIVE_STYLE_CONFLICT:' + ','.join(conflicts(style)))
    contract = info.get('style_contract', {})
    if not isinstance(contract, dict):
        contract = {}
    for field in STYLE_FIELDS:
        if not populated(contract.get(field)):
            errors.append('STYLE_CONTRACT_FIELD_MISSING:' + field)
        elif conflicts(contract[field]):
            errors.append('STYLE_CONTRACT_POSITIVE_CONFLICT:' + field)
    if mode == 'ANIMATED_COMIC':
        runtime_errors, _ = validate_runtime_budget(info, project.get('segments', []))
        errors.extend(runtime_errors)

for row in assets.get('assets', []) if isinstance(assets, dict) else assets:
    label = 'ASSET_' + str(row.get('asset_id', '?'))
    check_record(row, label)
    prompt = row.get('prompt')
    if populated(prompt):
        if populated(style) and style not in prompt:
            errors.append(label + ':FROZEN_STYLE_NOT_IN_POSITIVE_PROMPT')
        if conflicts(prompt):
            errors.append(label + ':POSITIVE_STYLE_CONFLICT:' + ','.join(conflicts(prompt)))
    elif row.get('reuse_existing') is not True or not populated(row.get('reuse_reason')):
        errors.append(label + ':PROMPT_OR_REUSE_REASON_REQUIRED')
for row in project.get('segments', []):
    label = 'SEGMENT_' + str(row.get('segment_id', '?'))
    check_record(row, label)
    if row.get('dialogue_capacity_status') == 'SPLIT_REQUIRED':
        errors.append(label + ':DIALOGUE_SPLIT_REQUIRED')
    estimate = row.get('estimated_spoken_s')
    if estimate is not None and (not number(estimate) or estimate < 0 or estimate > 4.6):
        errors.append(label + ':DIALOGUE_CAPACITY_INVALID')
for row in project.get('panels', []):
    label = 'PANEL_' + str(row.get('panel_id', '?'))
    check_record(row, label)
    if not populated(row.get('prompt')):
        errors.append(label + ':PANEL_PROMPT_MISSING')
    elif populated(style) and style not in row['prompt']:
        errors.append(label + ':FROZEN_STYLE_NOT_IN_POSITIVE_PROMPT')
    if conflicts(row.get('prompt')):
        errors.append('PANEL_' + str(row.get('panel_id', '?')) + ':POSITIVE_STYLE_CONFLICT')
for block in blocks or []:
    label = 'SEGMENT_' + str(block.index)
    if mode != 'ANIMATED_COMIC':
        errors.append(label + ':VIDEO_PROMPT_IN_STATIC_MODE')
    body = block.prompt
    head = 'detailed_description:' if 'detailed_description:' in body else 'integrated_multimodal_description:'
    detail = body.split(head, 1)[-1].split('overall_soundscape:', 1)[0]
    opening = detail.split('[Shot 1]', 1)[0]
    if populated(style) and style not in opening:
        errors.append(label + ':FROZEN_2D_STYLE_NOT_IN_OPENING')
    if conflicts(body):
        errors.append(label + ':H3_POSITIVE_STYLE_CONFLICT:' + ','.join(conflicts(body)))
return list(dict.fromkeys(errors))

def validate_plan(plan, project, assets, table=None):
    errors = validate_style_contract(project, assets)
    warnings = []
    def require(ok, message):
        if not ok:
            errors.append(message)
    require(plan.get('columns') == COLUMNS, 'SIX_COLUMN_SCHEMA: columns must match the source specification in order')
    require(plan.get('visual_medium') == '2D', 'PLAN_VISUAL_MEDIUM_NOT_2D')
    require(plan.get('style_id') == project.get('project', {}).get('style_id'), 'PLAN_STYLE_ID_MISMATCH')
    require(populated(plan.get('visual_style')), 'STYLE_MISSING')
    require(plan.get('visual_style') == project.get('project', {}).get('visual_style'), 'PROJECT_STYLE_MISMATCH')
    shots = plan.get('shots', [])
    segments = project.get('segments', [])
    if not isinstance(shots, list) or not isinstance(segments, list):
        return {'structure_status': 'FAIL', 'errors': ['SHOTS_OR_SEGMENTS_NOT_LIST']}
    multishot = shot_contract_enabled(project)
    mapped_rows = []
    if multishot:
        errors.extend(validate_schedule(project))
        for segment in segments:
            for shot in segment.get('shot_plan', []) if isinstance(segment.get('shot_plan'), list) else []:
                if isinstance(shot, dict):
                    mapped_rows.append((segment, shot))
        expected_mapping = [(s.get('segment_id'), p.get('shot_id')) for s,p in mapped_rows]
        require([(s.get('segment_id'), s.get('shot_id')) for s in shots] == expected_mapping, 'REAL_SHOT_SEGMENT_MAPPING_MISMATCH')
        require(len(shots) == len(mapped_rows) and bool(shots), 'REAL_SHOT_COUNT_MISMATCH')
    else:
        require(len(shots) == len(segments) and len(shots) > 0, 'SHOT_SEGMENT_COUNT_MISMATCH')
        require([s.get('segment_id') for s in shots] == [s.get('segment_id') for s in segments], 'SHOT_SEGMENT_ORDER_MISMATCH')
        mapped_rows = [(s, s) for s in segments]
        warnings.append('LEGACY_SEGMENT_ROWS: V6.1 generation must use real shots and a frozen shot_plan')
    ids = [s.get('shot_id') for s in shots]
    require(all(populated(x) for x in ids) and len(ids) == len(set(ids)), 'SHOT_ID_MISSING_OR_DUPLICATE')
    assets_by_name = {}
    for asset in assets.get('assets', []):
        assets_by_name.setdefault(asset.get('output_filename'), []).append(asset)
    for row, (segment, scheduled) in zip(shots, mapped_rows):
        label = row.get('shot_id', '?')
        duration = row.get('duration_s')
        require(finite_number(duration) and 0.2 <= duration <= 15.1, f'{label}: DURATION_OUTSIDE_AVS_RANGE')
        if finite_number(duration) and duration > 15:
            warnings.append(f'{label}: exceeds the community 15-second planning recommendation; check the actual model/workflow, do not silently shorten')
        require(duration == scheduled.get('duration_s'), f'{label}: SHOT_DURATION_MISMATCH' if multishot else f'{label}: SEGMENT_DURATION_MISMATCH')
        if multishot:
            for key, target in [('shot_number', scheduled.get('shot_number')), ('segment_start_s', scheduled.get('start_s')), ('segment_end_s', scheduled.get('end_s'))]:
                require(row.get(key) == target, f'{label}: SHOT_OFFSET_MAPPING_MISMATCH {key}')
        handoff = row.get('continuity_handoff', {})
        for field in ('incoming_state', 'end_state', 'from_previous', 'to_next'):
            require(populated(handoff.get(field)), f'{label}: HANDOFF_MISSING {field}')
        for field in ('incoming_state', 'end_state'):
            require(handoff.get(field) == scheduled.get(field), f'{label}: PROJECT_STATE_MISMATCH {field}')
        anchors = row.get('reference_anchors', {})
        for field in ('fixed_landmarks', 'characters', 'exited_character_status', 'lighting_baseline', 'scene_asset'):
            require(field in anchors, f'{label}: ANCHOR_FIELD_MISSING {field}')
        landmarks = anchors.get('fixed_landmarks', [])
        require(isinstance(landmarks, list), f'{label}: FIXED_LANDMARKS_NOT_LIST')
        for mark in landmarks if isinstance(landmarks, list) else []:
            require(populated(mark.get('id')) and populated(mark.get('screen_position')), f'{label}: LANDMARK_UNLOCATED')
        lighting = anchors.get('lighting_baseline', {})
        require(all(populated(lighting.get(k)) for k in ('key', 'fill', 'rim')), f'{label}: LIGHTING_BASELINE_MISSING')
        known_chars = {c.get('character_id') for c in segment.get('character_states', [])}
        bindings = set(segment.get('picture_bindings', {}).values())
        chars = anchors.get('characters', [])
        require(isinstance(chars, list), f'{label}: CHARACTERS_NOT_LIST')
        names = [anchors.get('scene_asset')]
        if 'local_area_asset' in anchors:
            names.append(anchors['local_area_asset'])
        for char in chars if isinstance(chars, list) else []:
            require(char.get('character_id') in known_chars, f'{label}: UNKNOWN_CHARACTER')
            require(all(populated(char.get(k)) for k in ('asset_name', 'screen_position', 'facing', 'initial_pose')), f'{label}: CHARACTER_BLOCKING_MISSING')
            names.append(char.get('asset_name'))
        for name in names:
            require(name in bindings, f'{label}: ANCHOR_ASSET_NOT_BOUND {name}')
            require(len(assets_by_name.get(name, [])) == 1, f'{label}: ANCHOR_ASSET_UNKNOWN_OR_AMBIGUOUS {name}')
        require(row.get('hook_type') in HOOKS, f'{label}: UNKNOWN_HOOK_TYPE')
        description = row.get('description', {})
        require(not conflicts(description.get('performance_style')), f'{label}: PERFORMANCE_STYLE_CONFLICT')
        if multishot:
            for field in ('shot_scale', 'camera_angle', 'camera_movement', 'composition', 'cut_reason'):
                require(description.get(field) == scheduled.get(field), f'{label}: FROZEN_CAMERA_PLAN_MISMATCH {field}')
        for field in ('shot_scale', 'camera_movement', 'performance_style', 'negative_constraints'):
            require(populated(description.get(field)), f'{label}: DESCRIPTION_MISSING {field}')
        require(description.get('video_model') == 'H3', f'{label}: NON_H3_ROW_IN_H3_EXPORT')
        timeline = description.get('per_second_directives', [])
        require(isinstance(timeline, list) and bool(timeline), f'{label}: TIMELINE_MISSING')
        previous = 0.0
        for index, entry in enumerate(timeline if isinstance(timeline, list) else []):
            start, end = entry.get('start_s'), entry.get('end_s')
            if not finite_number(start) or not finite_number(end):
                errors.append(f'{label}: INVALID_TIME {index}')
                continue
            require(abs(start-previous) < 1e-6, f'{label}: TIMELINE_GAP_OR_OVERLAP {index}')
            require(0 < end-start <= 1.000001, f'{label}: NOT_PER_SECOND {index}')
            for field in ('action', 'camera', 'spatial', 'audio', 'handoff'):
                require(populated(entry.get(field)), f'{label}: DIRECTIVE_MISSING {index} {field}')
            previous = end
        require(finite_number(duration) and abs(previous-duration) < 1e-6, f'{label}: TIMELINE_END_MISMATCH')
        require(populated(row.get('audio_track')), f'{label}: AUDIO_TRACK_MISSING')
    if table is not None:
        lines = [line.strip() for line in table.splitlines() if line.strip().startswith('|')]
        cells = [[x.strip().replace('\\|', '|') for x in re.split(r'(?<!\\)\|', line)[1:-1]] for line in lines]
        require(len(cells) >= 2 and cells[0] == COLUMNS, 'TABLE_HEADER_MISMATCH')
        rows = cells[2:]
        require(len(rows) == len(shots), 'TABLE_ROW_COUNT_MISMATCH')
        for cells_row, shot in zip(rows, shots):
            require(len(cells_row) == 6 and all(populated(v) for v in cells_row), f'{shot.get("shot_id")}: TABLE_NOT_SIX_COMPLETE_CELLS')
            if len(cells_row) == 6:
                require(cells_row[0] == f'{shot["shot_id"]} / {shot["duration_s"]:g}s', 'TABLE_SHOT_MAPPING_MISMATCH')
                require(cells_row[3] == shot.get('hook_type'), 'TABLE_HOOK_MISMATCH')
                if multishot:
                    mapping = f'AVS segment {shot["segment_id"]}, [Shot {shot["shot_number"]}], segment {shot["segment_start_s"]:g}–{shot["segment_end_s"]:g}s'
                    require(cells_row[1].startswith(mapping), f'{shot["shot_id"]}: TABLE_PARENT_MAPPING_MISMATCH')
    return {'structure_status': 'FAIL' if errors else 'PASS', 'shot_count': len(shots), 'segment_count':len(segments), 'mapping_mode':'REAL_SHOTS_TO_AVS_SEGMENTS' if multishot else 'LEGACY_SEGMENT_ROWS', 'errors': errors, 'warnings': warnings, 'semantic_continuity_status': 'NOT_REVIEWED_BY_THIS_CHECK', 'asset_content_status': 'UNVERIFIED', 'video_quality_status': 'NOT_TESTED'}

def main(path):
    text=Path(path).read_text(encoding="utf-8-sig").replace("\r\n","\n")
    lines=text.splitlines()
    starts=[]
    for i,line in enumerate(lines):
        if FORMAL.match(line) or LOCK.match(line): starts.append(i)
    errors=[]; warnings=[]; blocks=[]
    if not starts: errors.append("NO_WORKBENCH_HEADERS")
    for n,start in enumerate(starts):
        end=starts[n+1] if n+1<len(starts) else len(lines)
        head=lines[start]; fm=FORMAL.match(head); lm=LOCK.match(head)
        role="content" if fm else "hidden_anchor"
        ident=int(fm[1] or fm[2]) if fm else lm[1].strip()
        dur=float(fm[3] if fm else lm[2])
        chunk=lines[start:end]
        meta={}
        prompt_start=None
        for j,line in enumerate(chunk[1:],1):
            if START.match(line): prompt_start=j; break
            m=META.match(line)
            if m: meta[m[1]]=m[2].strip()
        if prompt_start is None:
            errors.append(f"{ident}:PROMPT_START_MISSING"); prompt=""
        else: prompt="\n".join(chunk[prompt_start:]).strip()
        blocks.append({"role":role,"id":ident,"duration":dur,"meta":meta,"prompt":prompt})
    formal=[b for b in blocks if b["role"]=="content"]
    ids=[b["id"] for b in formal]
    if ids!=list(range(1,len(ids)+1)): errors.append("FORMAL_IDS_NOT_CONSECUTIVE")
    lock_ids=[b["id"] for b in blocks if b["role"]=="hidden_anchor"]
    if len(lock_ids)!=len(set(lock_ids)): errors.append("DUPLICATE_LOCK_ID")
    for i,b in enumerate(blocks):
        m=b["meta"]
        for key in ["集数","场景","H3模式","连续性","继承尾音","生成模式","Picture绑定","Speaker绑定"]:
            if key not in m: errors.append(f"{b['id']}:META_MISSING:{key}")
        if m.get("H3模式","").upper()=="REF2VA":
            pos=[b["prompt"].find(x) for x in SECTIONS_REF]
            if any(x<0 for x in pos) or pos!=sorted(pos): errors.append(f"{b['id']}:REF2VA_SECTIONS_INVALID")
        raw_bind=m.get("Picture绑定","")
        bound=set() if raw_bind in {"","无","N/A","none"} else {x.upper() for x in re.findall(r"(?:^|[；;,，])\s*(P[1-9])\s*[=:：]",raw_bind,re.I)}
        refs={f"P{int(n)}" for n in re.findall(r"<Picture\s+(\d+)>",b["prompt"],re.I)}
        if bound != refs: errors.append(f"{b['id']}:PICTURE_BINDING_MISMATCH:bound={sorted(bound)},refs={sorted(refs)}")
        if b["role"]=="hidden_anchor":
            if not .2<=b["duration"]<=15.1: errors.append(f"{b['id']}:DURATION_OUTSIDE_AVS")
            if not .8<=b["duration"]<=1.5: warnings.append(f"{b['id']}:LOCK_DURATION_RECOMMENDED_0.8_TO_1.5S")
            if m.get("段类型")!="隐藏空间预热": errors.append(f"{b['id']}:ROLE_METADATA_INVALID")
            if m.get("成片")!="否": errors.append(f"{b['id']}:HIDDEN_MUST_NOT_BE_IN_FINAL")
            if m.get("空间锁ID")!=b["id"]: errors.append(f"{b['id']}:LOCK_ID_MISMATCH")
            if m.get("连续性")!="独立生成": errors.append(f"{b['id']}:LOCK_MUST_BE_INDEPENDENT")
            if m.get("继承尾音")!="否": errors.append(f"{b['id']}:LOCK_MUST_NOT_INHERIT_AUDIO")
            if "<d>" in b["prompt"]: errors.append(f"{b['id']}:LOCK_HAS_DIALOGUE")
            if i+1>=len(blocks) or blocks[i+1]["role"]!="content": errors.append(f"{b['id']}:LOCK_MUST_IMMEDIATELY_PRECEDE_FORMAL")
            else:
                nxt=blocks[i+1]
                if nxt["meta"].get("空间锁来源")!=b["id"]: errors.append(f"{b['id']}:NEXT_FORMAL_LOCK_SOURCE_MISMATCH")
                if nxt["meta"].get("连续性")!="续写上一段": errors.append(f"{b['id']}:NEXT_FORMAL_MUST_CONTINUE")
                if nxt["meta"].get("继承尾音")!="否": errors.append(f"{b['id']}:NEXT_FORMAL_MUST_NOT_INHERIT_LOCK_AUDIO")
                if nxt["meta"].get("场景")!=m.get("场景"): errors.append(f"{b['id']}:SCENE_MISMATCH")
        else:
            if m.get("段类型") not in {None,"正式视频段"}: errors.append(f"SEG{b['id']}:ROLE_METADATA_INVALID")
            if m.get("成片") not in {None,"是"}: errors.append(f"SEG{b['id']}:FORMAL_MUST_BE_IN_FINAL")
    payload={"ok":not errors,"formal_segments":len(formal),"hidden_locks":len(lock_ids),"errors":errors,"warnings":warnings}
    print(json.dumps(payload,ensure_ascii=False,indent=2))
    return 1 if errors else 0

